func TestEnumUploadMode(t *testing.T) {
	t.Run("NewFromString_service_proxied", func(t *testing.T) {
		t.Parallel()
		val, err := NewUploadModeFromString("service_proxied")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, UploadMode("service_proxied"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_direct_put", func(t *testing.T) {
		t.Parallel()
		val, err := NewUploadModeFromString("direct_put")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, UploadMode("direct_put"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_direct_multipart", func(t *testing.T) {
		t.Parallel()
		val, err := NewUploadModeFromString("direct_multipart")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, UploadMode("direct_multipart"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewUploadModeFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewUploadModeFromString("service_proxied")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

